"""Motor HTML5 gerado pela DSL de jogos Hzhon."""
from __future__ import annotations

import html
import json


def gerar_html(jogo: dict) -> str:
    dados = json.dumps(jogo, ensure_ascii=False).replace("</", "<\\/")
    titulo = html.escape(jogo["titulo"])
    dialogo = html.escape(jogo.get("dialogo", ""))
    dialogo_class = "" if dialogo else "hidden"
    template = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#07100f;color:#edf3ea;font:16px system-ui,sans-serif}main{width:min(100%,1000px);padding:20px}h1{font:400 clamp(26px,5vw,48px) Georgia,serif;margin:0 0 6px}p{opacity:.72;margin:0 0 16px}.game-wrap{position:relative;border:1px solid #36514a;border-radius:16px;overflow:hidden;background:#101b19;box-shadow:0 20px 70px #0008}canvas{display:block;width:100%;height:auto;image-rendering:auto}.hud{position:absolute;inset:14px 16px auto;display:flex;justify-content:space-between;gap:12px;pointer-events:none;font-weight:700;text-shadow:0 2px 5px #000}.dialog{position:absolute;left:6%;right:6%;bottom:8%;padding:16px 18px;border:1px solid #bce5d2;background:#10221fee;border-radius:12px;box-shadow:0 10px 30px #0008}.dialog strong{color:#f0c674}.dialog.hidden{display:none}button{border:0;border-radius:999px;padding:10px 16px;background:#bce5d2;color:#14211e;font-weight:700;cursor:pointer;margin-top:14px}.touch{display:flex;gap:8px;justify-content:center}.touch button{min-width:58px;background:#294d42;color:#edf3ea}@media(min-width:700px){.touch{display:none}}</style></head><body><main><h1>__TITLE__</h1><p>Jogo criado com Hzhon — sem escrever HTML ou JavaScript.</p><div class="game-wrap"><canvas id="jogo" width="__WIDTH__" height="__HEIGHT__"></canvas><div class="hud"><span id="estado">jogando</span><span>vidas <b id="vidas">__LIVES__</b> · pontos <b id="pontos">__POINTS__</b></span></div><div id="dialog" class="dialog __DIALOG_CLASS__"><strong>Hzhon diz:</strong> <span>__DIALOG__</span><br><small>Toque ou pressione Espaço para começar</small></div></div><div class="touch"><button data-key="left">◀</button><button data-key="up">▲</button><button data-key="right">▶</button></div><button id="reiniciar">Reiniciar jogo</button></main><script>const CONFIG=__DATA__,canvas=document.querySelector('#jogo'),ctx=canvas.getContext('2d'),keys={},estado=document.querySelector('#estado'),dialog=document.querySelector('#dialog'),vidasEl=document.querySelector('#vidas'),pontosEl=document.querySelector('#pontos');let ganhou=false,iniciado=!CONFIG.dialogo,vidas=CONFIG.vidas,pontos=CONFIG.pontos,camX=0,camY=0;const player={...CONFIG.jogadores[0],vx:0,vy:0,inicioX:CONFIG.jogadores[0].x,inicioY:CONFIG.jogadores[0].y};const inimigos=CONFIG.inimigos.map(x=>({...x,vx:1})),objetivo=CONFIG.objetivo,recorde=Number(localStorage.getItem('hzhon:'+CONFIG.titulo)||0);function caixa(o){return{x:o.x,y:o.y,w:o.tamanho||o.largura,h:o.tamanho||o.altura}}function toca(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}function som(f=440){if(!CONFIG.som)return;try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.frequency.value=f;g.gain.value=.035;o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.09)}catch(_){}}function comecar(){iniciado=true;dialog.classList.add('hidden')}function reiniciar(perdeu=false){player.x=player.inicioX;player.y=player.inicioY;player.vx=0;player.vy=0;ganhou=false;if(perdeu)vidas=CONFIG.vidas;estado.textContent='jogando';vidasEl.textContent=vidas;pontos=perdeu?CONFIG.pontos:pontos;pontosEl.textContent=pontos;comecar()}function desenhar(){ctx.fillStyle=CONFIG.fundo;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.save();ctx.translate(-camX,-camY);CONFIG.plataformas.forEach(p=>{ctx.fillStyle=p.cor;ctx.fillRect(p.x,p.y,p.largura,p.altura)});inimigos.forEach(e=>{ctx.fillStyle=e.cor;ctx.fillRect(e.x,e.y,e.tamanho,e.tamanho)});ctx.fillStyle=objetivo.cor;ctx.fillRect(objetivo.x,objetivo.y,objetivo.tamanho,objetivo.tamanho);ctx.fillStyle=player.cor;ctx.fillRect(player.x,player.y,player.tamanho,player.tamanho);ctx.restore()}function perderVida(){vidas--;som(150);vidasEl.textContent=vidas;if(vidas<=0){estado.textContent='game over';iniciado=false}else reiniciar()}function atualizar(){if(iniciado&&!ganhou&&vidas>0){const c=CONFIG.controles[player.nome]||{esquerda:'a',direita:'d',cima:'w'};player.vx=0;if(keys[c.esquerda]||keys['arrowleft'])player.vx=-4;if(keys[c.direita]||keys['arrowright'])player.vx=4;if((keys[c.cima]||keys['arrowup']||keys[' '])&&player.noChao){player.vy=-11;som(620)}player.vy+=.5;player.x=Math.max(0,player.x+player.vx);const antes=player.y;player.y+=player.vy;player.noChao=false;CONFIG.plataformas.forEach(p=>{const ch=caixa(p),pro=caixa(player);if(toca(pro,ch)&&antes+player.tamanho<=ch.y+4&&player.vy>=0){player.y=ch.y-player.tamanho;player.vy=0;player.noChao=true}});if(player.y>CONFIG.altura+100)perderVida();inimigos.forEach(e=>{e.x+=e.vx;if(e.x<0||e.x+e.tamanho>Math.max(canvas.width,CONFIG.largura))e.vx*=-1;if(toca(caixa(player),caixa(e)))perderVida()});if(toca(caixa(player),caixa(objetivo))){ganhou=true;pontos+=100;pontosEl.textContent=pontos;estado.textContent='vitória!';som(880);if(pontos>recorde)localStorage.setItem('hzhon:'+CONFIG.titulo,pontos)}}if(CONFIG.camera){camX=Math.max(0,Math.min(Math.max(0,CONFIG.largura-canvas.width),player.x-canvas.width*.35));camY=Math.max(0,Math.min(Math.max(0,CONFIG.altura-canvas.height),player.y-canvas.height*.45))}desenhar();requestAnimationFrame(atualizar)}window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' '&&!iniciado)comecar()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});dialog.onclick=comecar;document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=()=>{keys[b.dataset.key]=true;comecar()};b.onpointerup=()=>keys[b.dataset.key]=false});document.querySelector('#reiniciar').onclick=()=>reiniciar(true);vidasEl.textContent=vidas;pontosEl.textContent=pontos;atualizar();</script></body></html>'''
    return (template.replace("__TITLE__", titulo).replace("__WIDTH__", str(jogo["largura"]))
            .replace("__HEIGHT__", str(jogo["altura"])).replace("__LIVES__", str(jogo["vidas"]))
            .replace("__POINTS__", str(jogo["pontos"])).replace("__DIALOG__", dialogo)
            .replace("__DIALOG_CLASS__", dialogo_class).replace("__DATA__", dados))
